from typing import List, Tuple

def countVertex(N: int, edges: List[Tuple[int, int]]) -> int:
    if N == 1:
        return 1

    from collections import defaultdict

    graph = defaultdict(list)
    degree = [0] * (N + 1)

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
        degree[u] += 1
        degree[v] += 1

    leaves = [node for node in range(1, N + 1) if degree[node] == 1]
    result = 0

    while leaves:
        new_leaves = []
        for leaf in leaves:
            degree[leaf] = 0
            for neighbor in graph[leaf]:
                if degree[neighbor] > 0:
                    degree[neighbor] -= 1
                    if degree[neighbor] == 1:
                        new_leaves.append(neighbor)
        if new_leaves:
            result += 1
        leaves = new_leaves

    return result // 2 + (result % 2)
